// [START auth_svc_sign_in_email_react]
import { useActionState } from "react";
import { getAuth, signInWithEmailAndPassword } from "firebase/auth";

// Sign in screen.
function SignInForm() {
  const [error, signIn, isPending] = useActionState(async (previousError, formData) => {
    const auth = getAuth();
    try {
      await signInWithEmailAndPassword(auth, formData.get("email"), formData.get("password"));
      // Redirect to profile page after sign-in. The service worker will detect
      // this and append the ID token to the header.
      window.location.assign('/profile');
      return null;
    } catch (error) {
      // Error occurred.
      return error.message;
    }
  }, null);

  return (
    <form action={signIn}>
      <input name="email" type="email" />
      <input name="password" type="password" />
      <button type="submit" disabled={isPending}>Sign in</button>
      {error ? <p>{error}</p> : null}
    </form>
  );
}
// [END auth_svc_sign_in_email_react]